"""Original arctic monsters: tundra, pack ice, glaciers, and the long polar night."""
from monster_engine import M
R = lambda **k: "; ".join(f"<b>{a}</b> {b}" for a, b in k.items())
UNDEAD = "Charmed, Exhaustion, Frightened, Poisoned"
CONSTRUCT = "Charmed, Exhaustion, Frightened, Paralyzed, Petrified, Poisoned"
COLD_HARDY = ("Cold Hardy", "The {n} ignores the effects of extreme cold.")


def hardy(n):
    return (COLD_HARDY[0], COLD_HARDY[1].format(n=n))


